draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // freedom
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // responsibility
  ctx.beginPath();
  ctx.moveTo(W/2 + 70 + 30*Math.cos(t), H/2);
  ctx.lineTo(W/2 + 70 + 30*Math.cos(t + Math.PI/2), H/2 + 50 + 20*Math.sin(t));
  ctx.lineTo(W/2 + 70 + 30*Math.cos(t + Math.PI), H/2);
  ctx.closePath();
  ctx.stroke();

  // together
  ctx.beginPath();
  ctx.moveTo(W/2 - 70 - 30*Math.cos(t), H/2);
  ctx.lineTo(W/2 - 70 - 30*Math.cos(t + Math.PI/2), H/2 - 50 - 20*Math.sin(t));
  ctx.lineTo(W/2 - 70 - 30*Math.cos(t + Math.PI), H/2);
  ctx.closePath();
  ctx.stroke();

  ctx.restore();
}
